function persist(){try{localStorage.setItem('agent-desk-demo-v1',JSON.stringify({runs,connection,automation}));}catch{}}
try{const saved=JSON.parse(localStorage.getItem('agent-desk-demo-v1'));if(saved?.runs?.length&&saved.runs.every(r=>r.id&&Array.isArray(r.messages))){runs=saved.runs;connection=saved.connection!==false;automation=saved.automation!==false;}else seed();}catch{seed();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function go(route){mobileOpen=false;if(location.hash===`#/${route}`)render();else location.hash=`#/${route}`;}
function current(){const parts=(location.hash.slice(2)||'new').split('/');return {page:parts[0],id:parts[1]};}
function currentRun(){return runs.find(r=>r.id===current().id);}
function navItem(page,label,ico,count=''){return `<button class="nav-item ${current().page===page?'active':''}" data-nav="${page}">${icon(ico)}${label}${count?`<span class="count">${count}</span>`:''}</button>`;}
function sidebar(){const active=runs.filter(r=>activeStates.includes(r.state)).length;return `<div class="mobile-sidebar-backdrop ${mobileOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${mobileOpen?'open':''}" aria-label="Main navigation"><a href="#/new" class="brand"><img src="icon.svg" alt=""><div><strong>Agent Desk</strong><span>YOUR REMOTE WORKBENCH</span></div></a><div class="org-switch row"><span class="org-mark">N</span><span class="grow">Northstar engineering<small class="muted" style="display:block;font-size:9px">Demo organization</small></span>${icon('lock')}</div>${btn('New task','new','primary full','plus')}<div class="nav-label">WORKBENCH</div>${navItem('runs','All runs','layers',runs.length)}${navItem('workspaces','Workspaces','folder')}${navItem('automations','Automations','bolt')}<div class="nav-label">SETTINGS</div>${navItem('connections','AI connections','key')}<button class="nav-item" data-action="how">${icon('book')}How this demo works</button><div class="sidebar-bottom"><div class="cluster-card"><div class="row between"><span class="small" style="font-size:10px;font-weight:600">${icon('cloud')} Demo cluster</span><span class="dot green"></span></div><div class="cluster-bars"><span class="${active>0?'used':''}"></span><span class="${active>1?'used':''}"></span></div><div class="row between tiny muted"><span>${active} of 2 slots active</span><span>${runs.filter(r=>r.state==='queued').length} queued</span></div></div><div class="profile"><span class="avatar">AM</span><div class="grow"><strong style="font-size:11px;font-weight:550">Alex Morgan</strong><small class="muted" style="display:block;font-size:9px">Member · demo identity</small></div><button class="btn icon text" data-action="how" aria-label="About demo account">${icon('settings')}</button></div></div></aside>`;}
function render(){const route=current();const titles={new:'New task',runs:route.id?`Run #${route.id}`:'All runs',workspaces:'Workspaces',automations:'Automations',connections:'AI connections'};let content=route.page==='new'?newPage():route.page==='runs'?(route.id?runPage(currentRun()):runsPage()):route.page==='workspaces'?workspacePage():route.page==='automations'?automationPage():route.page==='connections'?connectionPage():newPage();$('#app').innerHTML=`<div class="app-shell">${sidebar()}<header class="topbar"><div class="row"><button class="btn icon mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb"><span>Northstar</span>${icon('chevron')}<strong>${esc(titles[route.page]||'New task')}</strong></div></div><div class="topbar-actions"><div class="prototype-label">${icon('box')} Interactive prototype<span> · mock data</span></div>${btn('Reset demo','reset','text','refresh')}</div></header><main class="main" id="main">${content}</main></div>`;document.title=`${titles[route.page]||'New task'} · Agent Desk`;
}
function newPage(){return `<div class="page-heading"><div><div class="heading-badge">${icon('play')} MANUAL RUN</div><h1>Give your agent a task.</h1><p>Choose the work. We’ll prepare the environment, away from your laptop.</p></div></div><div class="new-layout"><form id="manual-form" class="card" novalidate><section class="section"><div class="section-title"><span class="section-number">01</span><div><h2>What needs doing?</h2><p>Start with a template, then make it your own.</p></div></div><div class="task-types">${Object.entries(templates).map(([id,t])=>`<button type="button" class="template-card ${form.template===id?'selected':''}" data-template="${id}" aria-pressed="${form.template===id}">${icon(t.icon)}<div><strong>${t.name}</strong><span>${t.desc}</span></div>${form.template===id?'<i class="select-dot"></i>':''}</button>`).join('')}</div><div class="field"><label class="label" for="task-title">Task name</label><input id="task-title" data-form="title" value="${esc(form.title)}" maxlength="120" placeholder="A short name for this run" required></div><div class="field"><label class="label" for="task-prompt">Instructions <span class="muted" style="font-weight:400">· what should the agent do?</span></label><textarea id="task-prompt" data-form="prompt" maxlength="6000" rows="4" placeholder="Describe the change, expected result, and anything the agent should avoid." required>${esc(form.prompt)}</textarea><p class="hint">Be specific about the outcome. Workspace instructions will be included automatically.</p></div></section><section class="section"><div class="section-title"><span class="section-number">02</span><div><h2>Where should it work?</h2><p>Each run gets its own isolated copy of these repositories.</p></div></div><div class="field"><label class="label" for="workspace">Saved workspace</label><select id="workspace" data-form="workspace">${Object.entries(workspaces).map(([id,w])=>`<option value="${id}" ${form.workspace===id?'selected':''}>${w.name} · ${w.version}</option>`).join('')}</select></div><div class="row between" style="margin-bottom:8px"><span class="label" style="margin:0">Repositories</span><span class="tiny muted">Starting branch</span></div><div class="repo-box">${form.repos.map(r=>{const repo=repos.find(x=>x.id===r.id);return `<div class="repo-row"><label><input type="checkbox" data-repo="${r.id}" ${r.enabled?'checked':''}>${icon('repo','repo-icon')}<span><strong>${repo.org}/${repo.name}</strong><small>${repo.language} · private</small></span></label><label class="branch-input">${icon('git')}<input aria-label="Starting branch for ${repo.name}" value="${esc(r.branch)}" data-branch="${r.id}" maxlength="100"></label></div>`;}).join('')}</div><div class="repo-footer">${btn('Add repository','repos','text','plus')}<span class="tiny muted">Changes apply to this run only</span></div><div class="notice" style="margin-top:11px">${icon('file')}<span>Includes <strong>AGENTS.md</strong> and team instructions. The agent works on a new branch, not directly on main.</span></div></section><section class="section"><div class="section-title"><span class="section-number">03</span><div><h2>How should it run?</h2><p>Use an approved environment and an account you can access.</p></div></div><div class="field-grid"><div class="field"><label class="label" for="environment">Environment</label><select id="environment" data-form="env">${Object.entries(environments).map(([id,e])=>`<option value="${id}" ${form.env===id?'selected':''}>${e.name}</option>`).join('')}</select><p class="hint">${esc(environments[form.env].tools)}</p></div><div class="field"><label class="label" for="agent">Agent</label><select id="agent" data-form="agent"><option ${form.agent==='Codex'?'selected':''}>Codex</option><option ${form.agent==='Claude Code'?'selected':''}>Claude Code</option></select><p class="hint">Simulated agent output in this prototype.</p></div></div><label class="label">AI connection</label><label class="connection-option"><input type="radio" name="account" value="company" data-form="account" ${form.account==='company'?'checked':''}><span class="grow"><strong style="font-weight:550">Company ${form.agent==='Codex'?'OpenAI':'Anthropic'} account</strong><small>Usage-based API access · engineering team</small></span><span class="pill green">Demo connected</span></label>${form.agent==='Codex'?`<label class="connection-option"><input type="radio" name="account" value="personal" data-form="account" ${form.account==='personal'?'checked':''} ${!connection?'disabled':''}><span class="grow"><strong style="font-weight:550">My ChatGPT account</strong><small>Your subscription · only your authorized runs</small></span><span class="pill ${connection?'green':''}">${connection?'Demo connected':'Disconnected'}</span></label>`:''}${!connection&&form.agent==='Codex'?`<p class="hint"><a class="link-button" href="#/connections">Connect your account</a> to try the personal-account flow.</p>`:''}<p class="hint" style="margin-top:10px">${icon('lock')} No real credentials are stored or used in this demo.</p></section><details class="advanced" ${form.advanced?'open':''}><summary>Advanced settings <span class="row tiny muted">${sizes[form.size].cpu} CPU · ${sizes[form.size].memory} GiB ${icon('down')}</span></summary><div class="advanced-content"><div class="field"><label class="label">Resource size</label><div class="resource-options">${Object.entries(sizes).map(([id,s])=>`<button type="button" class="resource-option ${form.size===id?'selected':''}" data-size="${id}">${s.name}<span>${s.cpu} CPU · ${s.memory} GiB</span></button>`).join('')}</div><p class="hint">Up to two runs can be active at once in this demo. Additional runs wait in the queue.</p></div><div class="field-grid"><div class="field"><label class="label" for="timeout">Time limit</label><select id="timeout" data-form="timeout">${['15','30','60'].map(x=>`<option value="${x}" ${form.timeout===x?'selected':''}>${x} minutes</option>`).join('')}</select></div><div class="field"><label class="label" for="effort">Effort</label><select id="effort" data-form="effort">${['Standard','Thorough'].map(x=>`<option ${form.effort===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label class="label" for="completion">When the work is ready</label><select id="completion" data-form="completion"><option value="review" ${form.completion==='review'?'selected':''}>Prepare draft PR and suspend for review</option><option value="finish" ${form.completion==='finish'?'selected':''}>Save results and finish the run</option></select></div><div class="notice">${icon('shield')}<span>Network access is controlled by the selected environment. The demo does not expose cluster settings or raw image overrides.</span></div></div></details></form><aside class="summary-column"><div id="run-summary">${summary()}</div><div class="continue-card"><span class="pill amber">${icon('pause')} TRY THE REVIEW FLOW</span><h3>Pick up where an agent left off.</h3><p>A fix is ready. Review the changes, send feedback and restore its saved workspace.</p>${btn('Open saved run','open-saved','text','arrow')}</div><p class="demo-caption">Mock data only. No Kubernetes, GitHub<br>or AI requests are made.</p></aside></div>`;}
function summary(){const s=sizes[form.size];return `<div class="card summary-card"><div class="summary-title">${icon('layers')}<h2>Run summary</h2></div><span class="eyebrow">${templates[form.template].name}</span><h3 id="summary-title" style="margin-top:7px;font-size:14px;line-height:1.5">${esc(form.title||'Your new task')}</h3><div class="divider"></div><div class="summary-line"><span>Workspace</span><span>${workspaces[form.workspace].name}</span></div><div class="summary-line"><span>Repositories</span><span>${form.repos.filter(r=>r.enabled).length} selected</span></div><div class="summary-line"><span>Environment</span><span>${environments[form.env].short}</span></div><div class="summary-line"><span>Agent</span><span>${form.agent}</span></div><div class="summary-line"><span>Paid by</span><span>${form.account==='personal'?'My ChatGPT account':'Company API account'}</span></div><div class="resource-display"><div><strong>${s.cpu} <small>vCPU</small></strong><p>CPU LIMIT</p></div><div><strong>${s.memory} <small>GiB</small></strong><p>MEMORY LIMIT</p></div></div><div class="row tiny muted" style="gap:6px">${icon('clock')} ${form.timeout} min limit · ${form.completion==='review'?'suspend for review':'finish when done'}</div><div class="run-path"><span>Portal</span>${icon('arrow')}<span>AX</span>${icon('arrow')}<span>Substrate</span></div><p id="form-error" class="form-error" role="alert"></p><button class="btn primary full large" type="submit" form="manual-form">${icon('play')}Start demo run${icon('arrow')}</button><p class="summary-footnote">Simulates a full run in about 15 seconds.</p></div>`;}
function runsPage(){return `<div class="page-heading"><div><div class="heading-badge">${icon('layers')} WORKBENCH</div><h1>Your agent runs.</h1><p>Follow the work, review changes and continue saved sessions.</p></div>${btn('New task','new','primary','plus')}</div><div class="stats"><div class="card stat"><div class="muted row">${icon('activity')}Active now</div><div class="value">${runs.filter(r=>activeStates.includes(r.state)).length}<span class="small muted"> / 2</span></div></div><div class="card stat"><div class="muted row">${icon('message')}Needs your attention</div><div class="value">${runs.filter(r=>['review','input'].includes(r.state)).length}</div></div><div class="card stat"><div class="muted row">${icon('pause')}Suspended</div><div class="value">${runs.filter(r=>pausedStates.includes(r.state)).length}</div></div><div class="card stat"><div class="muted row">${icon('check')}Completed</div><div class="value">${runs.filter(r=>r.state==='completed').length}</div></div></div><div class="filters">${[['all','All runs'],['attention','Needs attention'],['active','Active'],['paused','Suspended'],['completed','Completed']].map(([id,t])=>`<button class="filter-btn ${filter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}<div class="search-box">${icon('search')}<input id="run-search" aria-label="Search runs" placeholder="Search runs…" value="${esc(search)}"></div></div><div class="card table-wrapper"><table class="run-table"><thead><tr><th>Task</th><th>Status</th><th>Environment</th><th>Owner / source</th><th></th></tr></thead><tbody id="run-rows">${runRows()}</tbody></table></div><p class="footer-note">Suspended runs retain saved state, not active sandbox CPU or RAM. Cluster and storage costs are separate.</p>`;}
function runRows(){const filtered=runs.filter(r=>(filter==='all'||filter==='attention'&&['review','input'].includes(r.state)||filter==='active'&&[...activeStates,'queued'].includes(r.state)||filter==='paused'&&pausedStates.includes(r.state)||filter==='completed'&&r.state==='completed')&&`${r.title} ${r.id}`.toLowerCase().includes(search.toLowerCase()));return filtered.length?filtered.map(r=>`<tr><td><button class="task-link" data-open-run="${r.id}">${esc(r.title)}</button><div class="subline">#${r.id} · ${esc(workspaces[r.workspace].name)} · ${esc(r.created)}</div></td><td>${badge(r.state)}<div class="subline">${pausedStates.includes(r.state)?'Sandbox suspended':activeStates.includes(r.state)?`${sizes[r.size].cpu} CPU · ${sizes[r.size].memory} GiB allocated`:r.state==='queued'?'Waiting for a slot':'No active sandbox'}</div></td><td>${esc(environments[r.env].short)}<div class="subline">${esc(r.agent)}</div></td><td>Alex Morgan<div class="subline">${esc(r.source)}</div></td><td><button class="btn icon" data-open-run="${r.id}" aria-label="Open ${esc(r.title)}">${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No runs match this view.</td></tr>';}
function runPage(r){if(!r)return `<div class="empty"><h2>Run not found</h2><p>This demo may have been reset.</p><br>${btn('Back to runs','runs','primary','arrow')}</div>`;const active=activeStates.includes(r.state),paused=pausedStates.includes(r.state),ended=['completed','cancelled','failed'].includes(r.state);return `<div class="page-heading run-heading"><div><div class="heading-badge"><a href="#/runs">ALL RUNS</a>${icon('chevron')}<span class="mono">RUN-${r.id}</span>${badge(r.state)}</div><h1 class="run-title">${esc(r.title)}</h1><div class="run-meta"><span class="row">${icon('folder')}${workspaces[r.workspace].name}</span><span class="small-dot"></span><span class="row">${icon('git')}${esc(r.branch)}</span></div></div><div class="run-actions">${paused?btn('Resume run','resume','primary','play'):active?btn('Suspend','suspend','','pause'):''}${!ended?btn('Cancel','cancel','','stop'):btn('Run again','rerun','','refresh')}</div></div><div class="run-layout"><section class="card"><div class="run-tabs" role="tablist" aria-label="Run output">${[['conversation','Conversation','message',r.messages.filter(m=>['user','agent'].includes(m.role)).length],['changes','Changes','code',r.diffs?.length||0],['tests','Tests','test',r.tests||0],['activity','Activity','activity','']].map(([id,title,ico,n])=>`<button class="run-tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-tab="${id}">${icon(ico)}${title}${n?`<span class="tab-count">${n}</span>`:''}</button>`).join('')}</div>${statusBanner(r)}${active?'<div class="progress-bar" aria-label="Simulated task is running"></div>':''}<div role="tabpanel">${tab==='conversation'?conversation(r):tab==='changes'?changes(r):tab==='tests'?tests(r):activity(r)}</div>${tab==='conversation'?composer(r):''}</section><aside class="run-side">${runSide(r)}</aside></div><p class="footer-note">All messages, tool results, diffs and infrastructure states shown here are simulated.</p>`;}
function statusBanner(r){const data={review:['pause','Saved and waiting for your review','The sandbox is suspended. Review the changes or send feedback to continue.','amber'],input:['message','The agent has a question for you','Your answer will restore the workspace and continue the saved session.','amber'],suspended:['pause','Paused. Your work is saved.','Resume this run whenever you’re ready. No active sandbox CPU or RAM.',''],queued:['clock','Waiting for a free slot','Your run will start when capacity is available. Maximum two active runs.','blue'],preparing:['box','Preparing an isolated workspace','Checking out repositories and starting the selected environment.','blue'],running:['activity','The agent is working','Follow its messages and tool results below. You can suspend or cancel.','blue'],resuming:['refresh','Restoring your saved workspace','Starting a fresh process and loading the saved agent session.','blue'],completed:['check','Run completed','Results are saved. No active sandbox. Finishing does not merge the PR.',''],cancelled:['stop','Run cancelled','The simulation has stopped. Existing messages and results are retained.',''],failed:['info','Run failed','No active sandbox. Review the output before creating a new run.','amber']}[r.state];return `<div class="run-status-banner ${data[3]}">${icon(data[0],r.state==='resuming'?'spin':'')}<div class="grow"><strong>${data[1]}</strong><p>${data[2]}</p></div></div>`;}
function conversation(r){return `<div class="tab-description">Agent messages and observable tool output. Not the model’s private reasoning.</div><div class="conversation" id="conversation">${r.messages.map(m=>m.role==='system'?`<div class="system-message">${icon(m.text.toLowerCase().includes('suspend')?'save':'check')}<span>${esc(m.text)}</span></div>`:m.role==='tool'?`<details class="tool-block"><summary>${icon('terminal')}<span class="mono">${esc(m.text)}</span><span class="tool-status">${esc(m.status||'Done')}</span>${icon('down')}</summary><pre>${esc(m.output||'')}</pre></details>`:`<article class="message ${m.role}"><span class="message-avatar ${m.role==='user'?'user':''}">${m.role==='user'?'MH':icon('terminal')}</span><div class="grow"><div class="message-head"><strong>${m.role==='user'?'You':esc(r.agent)}</strong>${m.role==='agent'?'<span class="pill" style="font-size:8px;padding:0 4px">AGENT</span>':''}<span class="message-time">${m.time}</span></div><div class="message-body">${md(m.text)}</div></div></article>`).join('')}${activeStates.includes(r.state)?`<div class="system-message">${icon('activity','pulse')}<span>${r.state==='resuming'?'Restoring the session…':'Simulating the next step…'}</span></div>`:''}</div>`;}
function composer(r){if(['completed','cancelled','failed'].includes(r.state))return `<div class="composer-wrap row between wrap"><span class="small muted">This run is closed. Its results remain available.</span>${btn('Run again','rerun','','refresh')}</div>`;if(['preparing','resuming','queued'].includes(r.state))return `<div class="composer-wrap"><p class="small muted">${r.state==='queued'?'Your task is queued. No sandbox has been allocated.':'The conversation will be available when the environment is ready.'}</p></div>`;const paused=pausedStates.includes(r.state);return `<div class="composer-wrap">${r.state==='review'?`<div class="row between wrap" style="margin-bottom:13px"><span class="small muted">Happy with the changes?</span>${btn('Approve & finish','approve','soft','check')}</div>`:''}${paused?`<div class="suggestions">${(r.state==='input'?['Only filtered orders, without email addresses.','All orders, without personal data.']:['Add a test for concurrent requests.','Explain the changes before continuing.']).map(x=>`<button class="suggestion" data-suggestion="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:''}<div class="composer"><label class="hidden" for="feedback">${paused?'Feedback for the agent':'Message for the agent'}</label><textarea id="feedback" placeholder="${r.state==='input'?'Answer the agent’s question…':paused?'What should the agent change or check next?':'Send a follow-up instruction…'}">${esc(r.draft||'')}</textarea><div class="composer-actions"><span class="small row">${icon(paused?'save':'message')}${paused?'Restores workspace + saved session':'Queued for the next agent step'}</span>${btn(paused?'Send & resume':'Send message',paused?'compose-resume':'send','primary',paused?'play':'arrow')}</div></div>${paused?'<p class="hint">Feedback stays in this run. To change the image or repositories, create a new run.</p>':''}</div>`;}
function changes(r){if(!r.diffs?.length)return `<div class="empty">${icon('code')}<h3 style="margin-top:12px">No changes yet</h3><p>The agent’s file changes will appear here.</p></div>`;return `<div class="file-list"><div class="row between" style="padding:4px 0 17px"><span class="small muted">${r.diffs.length} changed files · sample diff</span><span class="mono"><span class="green">+${r.diffs.reduce((n,f)=>n+f.add,0)}</span> <span style="color:#b77c64">−${r.diffs.reduce((n,f)=>n+f.remove,0)}</span></span></div>${r.diffs.map(f=>`<details class="diff-file" open><summary>${icon('file')}<span class="grow mono" style="font-size:10px">${esc(f.name)}</span><span class="green">+${f.add}</span><span style="color:#b77c64">−${f.remove}</span></summary><pre>${f.lines.map(l=>`<span class="diff-line ${l.startsWith('+')?'add':l.startsWith('-')?'remove':''}">${esc(l)}</span>`).join('')}</pre></details>`).join('')}</div>`;}
function tests(r){if(!r.tests)return `<div class="empty">${icon('test')}<h3 style="margin-top:12px">Tests have not run yet</h3><p>Command output and test results will appear here.</p></div>`;return `<div class="tests-panel"><div class="test-summary">${icon('check')}<div class="grow"><strong>${r.tests} tests passed</strong><p class="tiny muted">0 failed · 0 skipped · simulated result</p></div><span class="mono muted">3.2s</span></div><p class="eyebrow" style="margin-bottom:8px">SELECTED TESTS</p>${['SameKey_ReturnsOriginalOrder','DifferentKeys_CreateSeparateOrders','MissingKey_ReturnsValidationError','InvalidAmount_IsRejected',...(r.iteration>0?['ConcurrentRequests_ReturnSameOrder']:[])].map((t,i)=>`<div class="test-row">${icon('check')}<span class="mono grow">${t}</span><span class="mono muted">${12+i*7}ms</span></div>`).join('')}<div class="notice" style="margin-top:20px">${icon('info')}<span>These are illustrative test results. This prototype does not execute code.</span></div></div>`;}
function activity(r){return `<div class="activity-list"><p class="eyebrow" style="margin-bottom:12px">RUN HISTORY</p>${r.messages.filter(m=>m.role==='system'||m.role==='tool').map(m=>`<div class="activity-item"><span class="mono">${m.time}</span><div>${esc(m.text)}${m.status?`<div class="tiny muted">${esc(m.status)}</div>`:''}</div></div>`).join('')}${!r.messages.some(m=>m.role==='system')?'<p class="muted small">Run created. Waiting for the first activity.</p>':''}</div>`;}
function runSide(r){const paused=pausedStates.includes(r.state),active=activeStates.includes(r.state);let checkpoint=r.state==='completed'?4:r.state==='review'?3:r.state==='resuming'?1:r.state==='preparing'||r.state==='queued'?0:2;return `<div class="card"><div class="row between"><h3>Execution</h3><span class="pill ${active?'blue':''}">${active?'Active':paused?'Suspended':r.state==='queued'?'Not allocated':'Released'}</span></div><div class="resource-display" style="margin:16px 0 8px"><div><strong>${active?sizes[r.size].cpu:'0'} <small>vCPU</small></strong><p>ALLOCATED</p></div><div><strong>${active?sizes[r.size].memory:'0'} <small>GiB</small></strong><p>ALLOCATED</p></div></div><p class="tiny muted">${paused?'Saved state uses storage only. Cluster capacity may still incur costs.':active?'Simulated allocation, not a real usage metric.':'No active sandbox for this run.'}</p><ol class="progress-steps">${['Prepare workspace','Start agent session','Build & test','Wait for review','Finish'].map((s,i)=>`<li class="${i<checkpoint?'done':i===checkpoint?'current':''}"><span>${i<checkpoint?icon('check'):i===checkpoint?'•':''}</span>${s}</li>`).join('')}</ol></div>${r.snapshot?`<div class="card"><div class="row"><span class="snapshot-icon">${icon('save')}</span><div><h3>Saved checkpoint</h3><span class="tiny muted">${r.savedAt||'Just now'} · ${r.snapshot}</span></div></div><div class="side-detail"><p>${icon('check')} Repository files & local changes</p><p>${icon('check')} Saved agent conversation</p><p>${icon('check')} Run metadata</p></div><p class="hint" style="margin-top:13px">Resume starts a fresh process and continues from saved session data. Credentials are not part of this demo snapshot.</p></div>`:''}<div class="card"><h3>Run configuration</h3><div class="side-detail"><span class="side-label">Environment</span><p>${environments[r.env].short}</p></div><div class="side-detail"><span class="side-label">Agent / connection</span><p>${esc(r.agent)} · ${r.account==='personal'?'My ChatGPT':'Company API'}</p></div><div class="side-detail"><span class="side-label">Repositories</span>${r.repos.filter(x=>x.enabled).map(x=>`<p class="mono" style="font-size:10px">${esc(x.id)} <span class="muted">@ ${esc(x.branch)}</span></p>`).join('')}</div><div class="side-detail"><span class="side-label">Limit / owner</span><p>${r.timeout} minutes · Alex Morgan</p></div>${r.diffs?.length?`<div class="divider"></div>${btn('Preview draft PR','pr','full','git')}`:''}</div>`;}
function workspacePage(){return `<div class="page-heading"><div><div class="heading-badge">${icon('folder')} REUSABLE ENVIRONMENTS</div><h1>A familiar starting point.</h1><p>Repository choices and instructions, ready for your next task.</p></div></div><div class="workspace-grid">${Object.entries(workspaces).map(([id,w])=>`<section class="card workspace-card"><div class="row between"><span class="kicker-box">${icon('folder')}</span><span class="pill">Team workspace · ${w.version}</span></div><h2>${w.name}</h2><p>${w.desc}</p><div class="workspace-repos">${w.repos.map(id=>`<span>${id}</span>`).join('')}</div><div class="notice">${icon('file')}<span>AGENTS.md + shared team instructions</span></div><div class="card-bottom"><span class="tiny muted">${environments[w.env].short}</span><button class="btn soft" data-use-workspace="${id}">${icon('plus')}Use workspace</button></div></section>`).join('')}</div><div class="connection-note">${icon('info')} Selecting a workspace creates a separate working copy for each run. You can change the repository selection and branches in the run form without editing the shared definition.</div>`;}
function connectionPage(){return `<div class="page-heading"><div><div class="heading-badge">${icon('key')} AI CONNECTIONS</div><h1>Your accounts, clearly separated.</h1><p>Choose which connection a run uses. No automatic switching between accounts.</p></div></div><div class="connection-grid"><section class="card connection-card"><div class="row between">${icon('server')}<span class="pill green">Demo connected</span></div><h2>Company API accounts</h2><p>OpenAI for Codex and Anthropic for Claude Code. Available to the engineering team.</p><div class="connection-facts"><span>Owner<br><strong>Northstar engineering</strong></span><span>Access<br><strong>Team-approved runs</strong></span></div><div class="notice">${icon('shield')}<span>Company credentials would be managed by the backend. No API keys are present in this prototype.</span></div></section><section class="card connection-card"><div class="row between">${icon('user')}<span class="pill ${connection?'green':''}">${connection?'Demo connected':'Disconnected'}</span></div><h2>My ChatGPT account</h2><p>A personal Codex connection for your authorized runs. Separate from your portal sign-in.</p><div class="connection-facts"><span>Owner<br><strong>Alex Morgan</strong></span><span>Concurrency<br><strong>1 run at a time</strong></span></div>${btn(connection?'Disconnect demo account':'Try connection flow',connection?'disconnect':'connect',connection?'':'primary',connection?'logout':'key')}</section></div><div class="connection-note">${icon('lock')} This is a UX simulation. It never asks for passwords, API keys or real login codes. Subscription access, token refresh and per-user isolation require a real backend integration.</div>`;}
function automationPage(){return `<div class="page-heading"><div><div class="heading-badge">${icon('bolt')} EVENT-DRIVEN TASKS</div><h1>Let the right event start the work.</h1><p>A saved rule uses the same task settings as a manual run.</p></div></div><section class="card automation-card"><div class="row between"><div><h2>Issue → proposed fix</h2><p class="small muted" style="margin-top:5px">Example rule · northstar/orders-api</p></div><div class="row"><span class="tiny muted">${automation?'Enabled in demo':'Disabled'}</span><button class="toggle ${automation?'on':''}" data-action="toggle-automation" aria-label="Enable demo automation" role="switch" aria-checked="${automation}"><span></span></button></div></div><div class="automation-flow"><div class="automation-node">${icon('git')}<h3>Issue labelled</h3><p>A maintainer adds <code>agent-fix</code></p></div>${icon('arrow')}<div class="automation-node">${icon('bug')}<h3>Fix an issue</h3><p>Orders platform · company API</p></div>${icon('arrow')}<div class="automation-node">${icon('pause')}<h3>Draft PR + review</h3><p>Save state and suspend</p></div></div><div class="row between wrap"><div class="notice grow">${icon('shield')}<span>In production: verify webhook signatures, check actor permissions and deduplicate deliveries.</span></div>${btn('Trigger demo event','trigger-event','primary','bolt',automation?'':'disabled')}</div></section><p class="footer-note">No webhook is registered. Triggering creates a local, simulated run only.</p>`;}
function openModal(type,id){returnFocus=document.activeElement;modalState={type,id:id||current().id};renderModal();setTimeout(()=>{const root=$('.modal');const focus=$('textarea',root)||$('input',root)||$('button',root);focus?.focus();},40);}
function closeModal(){modalState=null;$('#modal-root').innerHTML='';document.body.style.overflow='';returnFocus?.focus();}
function renderModal(){if(!modalState)return;const {type,id}=modalState;const r=runs.find(x=>x.id===id);let title='',subtitle='',body='',footer='',wide=false;
 if(type==='resume'&&r){title=r.state==='input'?'Answer & resume':'Continue this run';subtitle='Restore the environment. Keep the context.';body=`<div class="resume-summary"><div><dt>Task</dt><dd>${esc(r.title)}</dd></div><div><dt>Connection</dt><dd>${r.account==='personal'?'My ChatGPT account':'Company API account'}</dd></div><div><dt>Environment</dt><dd>${environments[r.env].short}</dd></div><div><dt>Resources when active</dt><dd>${sizes[r.size].cpu} CPU · ${sizes[r.size].memory} GiB</dd></div></div><div class="notice">${icon('save')}<span>Restore repository files and the saved conversation. A fresh agent process continues the session. It does not start the task from scratch.</span></div><label class="label" for="resume-feedback">${r.state==='input'?'Your answer':'Feedback for the agent'} ${r.state==='suspended'?'<span class="muted">(optional)</span>':''}</label><textarea id="resume-feedback" placeholder="${r.state==='input'?'Tell the agent how to proceed…':'For example: add a test for concurrent requests.'}" rows="4">${esc(r.draft||'')}</textarea><p class="hint">This keeps the same repositories, environment and AI connection.</p><p id="modal-error" class="form-error" role="alert"></p>`;footer=btn('Not now','close-modal')+btn('Resume with feedback','confirm-resume','primary','play');}
 else if(type==='approve'&&r){title='Finish this run?';subtitle='Keep the results and release the saved execution environment.';body=`<div class="notice green">${icon('check')}<span>${r.tests} simulated tests passed. Changes are ready in the draft PR preview.</span></div><p class="readme">The run will be marked completed. Conversation, test results and code changes remain available in this demo.</p><p class="readme" style="margin-top:12px"><strong>This does not merge a pull request.</strong> Repository approval and merging would remain a separate action.</p>`;footer=btn('Keep reviewing','close-modal')+btn('Approve & finish','confirm-approve','primary','check');}
 else if(type==='cancel'&&r){title='Cancel this run?';subtitle='This is different from suspending it.';body='<p class="readme">The simulation will stop and the run cannot be resumed. Existing messages and results remain available. You can create a new run later.</p>';footer=btn('Keep run','close-modal')+btn('Cancel run','confirm-cancel','danger','stop');}
 else if(type==='repos'){title='Add a repository';subtitle='Choose from repositories this demo user can access.';body=repos.map(repo=>`<label class="repo-choice"><input type="checkbox" data-add-repo="${repo.id}" ${form.repos.some(x=>x.id===repo.id&&x.enabled)?'checked':''}>${icon('repo')}<span><strong>${repo.org}/${repo.name}</strong><p>${repo.language} · private · authorized in this demo</p></span></label>`).join('');footer=btn('Cancel','close-modal')+btn('Update selection','confirm-repos','primary','check');}
 else if(type==='connect'){title='Connect your ChatGPT account';subtitle='Preview of a device-code sign-in experience.';body=`<div class="notice amber">${icon('info')}<span><strong>Simulation only.</strong> Do not enter this code anywhere. No real authentication is started.</span></div><div class="code-demo"><strong>DEMO-1234</strong><p>ILLUSTRATIVE CODE · NOT VALID</p></div><p class="readme">In the real application, you would open the official provider’s verification page, sign in there, and authorize your own connection. The portal would never ask for your password.</p>`;footer=btn('Cancel','close-modal')+btn('Simulate successful sign-in','confirm-connect','primary','check');}
 else if(type==='disconnect'){title='Disconnect the demo account?';subtitle='Personal-account runs will require reconnection.';body='<p class="readme">New runs cannot use this connection. Already-running simulations will stop, and saved personal-account runs cannot resume until you reconnect. Company-account runs are unaffected.</p>';footer=btn('Keep connected','close-modal')+btn('Disconnect','confirm-disconnect','danger','logout');}
 else if(type==='reset'){title='Reset the prototype?';subtitle='Restore the original sample runs and settings.';body='<p class="readme">This clears only this prototype’s data in your browser. Your demo-created runs and messages will be removed. No real systems are affected.</p>';footer=btn('Keep my demo runs','close-modal')+btn('Reset demo','confirm-reset','primary','refresh');}
 else if(type==='pr'&&r){title=`Draft PR #${r.id==='1048'?'87':Number(r.id)-961}`;subtitle='Local preview only. Nothing was published to GitHub.';wide=true;body=`<div class="row wrap" style="margin:7px 0 18px"><span class="pill">Draft</span><span class="mono">${esc(r.branch)}</span>${icon('arrow')}<span class="mono">main</span></div><h2 style="margin-bottom:12px">${esc(r.title)}</h2><div class="readme"><h3>Summary</h3><p>A proposed change based on the task instructions, with regression coverage and a test report.</p><h3>Validation</h3><p>${r.tests} simulated tests passed. ${r.diffs.length} sample files changed.</p><h3>Review notes</h3><p>Check the behavior and test coverage. Send feedback in the run conversation to restore the environment and ask the agent for a revision.</p></div><div class="notice">${icon('info')}<span>This is illustrative PR content, not evidence of a real code change.</span></div>`;footer=btn('Back to run','close-modal','primary','arrow');}
 else {title='A workbench for remote agents';subtitle='Clickable UX prototype. No real services connected.';wide=true;body=`<div class="readme"><h3>Try the complete flow</h3><p>1. Start a task from <strong>New task</strong>.<br>2. Watch simulated messages, tool output and test results.<br>3. The sandbox suspends when review is needed.<br>4. Send feedback to restore the saved workspace and continue.<br>5. Approve and finish, without merging any PR.</p><h3>Try an agent question</h3><p>Open <strong>Add CSV export for orders</strong> from All runs. Answer its question and resume.</p><h3>What is saved?</h3><p>Real AX integrations need both workspace files and agent session data. The proposed resume flow restarts a process and continues the saved conversation, rather than assuming process memory is restored.</p><h3>What is mocked?</h3><p>Everything: identity, accounts, repositories, model messages, tests, code changes, snapshots and compute. This app stores only demo state in your browser. No AI, GitHub or Kubernetes API calls are made.</p><h3>What needs a backend?</h3><p>User authorization, credential handling, task queuing, AX integration, event verification, artifact storage and agent adapters. A private AX API should sit behind an authenticated application backend.</p></div>`;footer=btn('Got it','close-modal','primary','check');}
 $('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="btn icon" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-content">${body}</div><footer class="modal-footer">${footer}</footer></section></div>`;document.body.style.overflow='hidden';
}
function updateSummary(){const el=$('#run-summary');if(el)el.innerHTML=summary();}
function chooseWorkspace(id){form.workspace=id;form.repos=workspaces[id].repos.map(id=>({id,enabled:true,branch:'main'}));form.env=workspaces[id].env;}
function createRun(config,source='Manual'){
 const id=String(Math.max(1048,...runs.map(r=>Number(r.id)))+1);
 const r={...structuredClone(config),id,state:'queued',source,owner:'Alex Morgan',created:`Today, ${time()}`,branch:`agent/task-${id}`,messages:[],diffs:[],tests:0,step:0,iteration:0,snapshot:null,savedAt:null,nextAt:Date.now()+900,draft:''};
 addMessage(r,'user',r.prompt);addMessage(r,'system',`${source==='GitHub event'?'Demo webhook matched. ':''}Run queued with ${r.account==='personal'?'your personal ChatGPT connection':'the company API connection'}.`);runs.unshift(r);persist();tab='conversation';go(`runs/${id}`);toast('Demo run created. No real infrastructure was started.');
}
function startManual(){const err=$('#form-error');let msg='';if(!form.title.trim())msg='Give the task a name.';else if(!form.prompt.trim())msg='Add instructions for the agent.';else if(!form.repos.some(r=>r.enabled))msg='Select at least one repository.';else if(form.repos.some(r=>r.enabled&&!r.branch.trim()))msg='Choose a starting branch for each selected repository.';else if(form.account==='personal'&&!connection)msg='Reconnect your ChatGPT demo account first.';if(msg){err.textContent=msg;err.scrollIntoView({block:'nearest',behavior:'smooth'});return;}createRun(form);}
function saveCheckpoint(r){r.snapshot=`snap_${r.id}_${String((r.iteration||0)+1).padStart(2,'0')}`;r.savedAt=time();}
function canStart(r){return runs.filter(x=>activeStates.includes(x.state)).length<2&&(r.account!=='personal'||!runs.some(x=>x.id!==r.id&&x.account==='personal'&&activeStates.includes(x.state)));}
function resumeRun(r,feedback){if(!r||!pausedStates.includes(r.state))return;if(r.account==='personal'&&!connection){toast('Reconnect your ChatGPT demo account before resuming.');return;}if(!feedback.trim()&&r.state!=='suspended'){const e=$('#modal-error');if(e)e.textContent='Add feedback or an answer so the agent knows what to do next.';else toast('Write feedback, or choose Approve & finish.');return;}if(feedback.trim())addMessage(r,'user',feedback.trim());r.draft='';r.iteration=(r.iteration||0)+1;r.step=0;r.isResume=true;r.nextAt=Date.now()+1800;if(canStart(r)){r.state='resuming';addMessage(r,'system','Restoring the saved workspace and agent session. Rechecking the selected AI connection.');}else{r.state='queued';addMessage(r,'system','Resume requested. Waiting for capacity or for your personal account’s current run to finish.');}persist();closeModal();tab='conversation';refreshUI();toast(r.state==='queued'?'Resume queued.':'Restoring the saved run…');}
function mockDiffs(r){if(r.env==='dotnet')return structuredClone(demoDiffs);if(r.env==='node')return [{name:'src/orders/service.ts',add:8,remove:2,lines:['  export async function createOrder(request: OrderRequest) {','+   const existing = await repository.findByKey(request.key);','+   if (existing) return existing;','-   return repository.insert(request);','+   return repository.insertIfAbsent(request);','  }']},{name:'tests/orders.spec.ts',add:9,remove:0,lines:["+ it('returns the original order for repeated requests', async () => {",'+   const first = await service.create(request);','+   const retry = await service.create(request);','+   expect(retry.id).toBe(first.id);','+ });']}];return [{name:'app/orders.py',add:6,remove:1,lines:['  async def create_order(request):','+     existing = await repo.find_by_key(request.key)','+     if existing:','+         return existing','-     return await repo.insert(request)','+     return await repo.insert_if_absent(request)']},{name:'tests/test_orders.py',add:7,remove:0,lines:['+ async def test_repeated_request_returns_original_order():','+     first = await service.create(request)','+     retry = await service.create(request)','+     assert first.id == retry.id']}];}
function tick(){let changed=false;const now=Date.now();for(const r of [...runs].reverse()){
 if(r.state==='queued'&&r.nextAt<=now){if(r.account==='personal'&&!connection){r.state='suspended';addMessage(r,'system','Connection disconnected. Reconnect before continuing.');changed=true;continue;}if(!canStart(r))continue;r.state=r.isResume?'resuming':'preparing';r.nextAt=now+1700;addMessage(r,'system',r.isResume?'Restoring saved workspace and session.':'Sandbox allocated. Checking out the selected repositories and loading workspace instructions.');changed=true;}
 else if(['preparing','resuming'].includes(r.state)&&r.nextAt<=now){const restored=r.state==='resuming';r.state='running';r.step=0;r.nextAt=now+2400;addMessage(r,'system',restored?'Workspace restored. A fresh agent process loaded the previous session.':'Workspace ready. The agent is running in its own working copy.');addMessage(r,'agent',restored?'I have the saved workspace and your latest feedback. I’ll continue from the existing changes, then run the tests again.':`I’ll inspect ${r.repos.filter(x=>x.enabled).map(x=>x.id).join(' and ')}, follow the workspace instructions, and work on a separate branch. I’ll report the changes and test results before finishing.`);changed=true;}
 else if(r.state==='running'&&r.nextAt<=now){r.nextAt=now+2400;
  if(r.step===0){addMessage(r,'tool','git status --short', {output:`On branch ${r.branch}\n${r.isResume?'Existing changes restored from checkpoint.':'Working tree ready.'}\nSelected repositories available.`,status:'Ready'});r.step++;}
  else if(r.step===1){addMessage(r,'agent',r.isResume?'I’m updating the proposed change based on your feedback and adding a regression test. The next step is validation.':'I have enough context to make a focused change. I’m updating the implementation and adding regression coverage. The code shown here is sample output for this UX demo.');r.step++;}
  else if(r.step===2){r.diffs=mockDiffs(r);r.tests=24+(r.iteration||0);addMessage(r,'tool',r.env==='dotnet'?'dotnet test --no-restore':r.env==='node'?'pnpm test':'pytest -q',{output:`Tests: ${r.tests} passed · 0 failed · 0 skipped\nDuration: 3.2s\nThis result is simulated.`,status:`${r.tests} passed`});r.step++;}
  else{const done=r.completion==='finish';addMessage(r,'agent',`**${r.isResume?'The revision':'The proposed change'} is ready${done?'':' for review'}.**\n\n${r.diffs.length} sample files changed and ${r.tests} simulated tests passed. You can inspect the diff and test report in the tabs above.\n\n${done?'I saved the results. This run can now finish.':'Review the draft PR preview, or send feedback if you want another revision.'}`);r.state=done?'completed':'review';if(!done)saveCheckpoint(r);else r.snapshot=null;addMessage(r,'system',done?'Run completed. Sandbox released. Results remain in the portal.':'Workspace and agent session saved. Sandbox suspended while waiting for review. No active sandbox CPU or RAM.');r.isResume=false;}
  changed=true;
 }
}if(changed){persist();refreshUI();}}
function refreshUI(){const focused=document.activeElement;const id=focused?.id;const start=focused?.selectionStart;const end=focused?.selectionEnd;const scroll=window.scrollY;const opened=[...document.querySelectorAll('.tool-block')].map(x=>x.open);render();document.querySelectorAll('.tool-block').forEach((x,i)=>{if(opened[i])x.open=true;});if(id){const next=document.getElementById(id);if(next){next.focus({preventScroll:true});if(typeof start==='number'&&typeof next.setSelectionRange==='function')try{next.setSelectionRange(start,end);}catch{}}}window.scrollTo(0,scroll);}
document.addEventListener('submit',e=>{if(e.target.id==='manual-form'){e.preventDefault();startManual();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.form){form[el.dataset.form]=el.value;if(el.dataset.form==='title'){const title=$('#summary-title');if(title)title.textContent=el.value||'Your new task';}}if(el.dataset.branch){const repo=form.repos.find(r=>r.id===el.dataset.branch);repo.branch=el.value;}if(el.id==='run-search'){search=el.value;$('#run-rows').innerHTML=runRows();}if(el.id==='feedback'){const r=currentRun();if(r){r.draft=el.value;persist();}}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.form){const key=el.dataset.form;form[key]=el.value;if(key==='workspace')chooseWorkspace(el.value);if(key==='agent')form.account='company';if(el.matches('select')||el.type==='radio')refreshUI();}if(el.dataset.repo){form.repos.find(r=>r.id===el.dataset.repo).enabled=el.checked;updateSummary();}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.advanced'))form.advanced=e.target.open;},true);
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
 const tpl=e.target.closest('[data-template]');if(tpl){const t=templates[tpl.dataset.template];form.template=tpl.dataset.template;form.title=t.title;form.prompt=t.prompt;refreshUI();return;}
 const size=e.target.closest('[data-size]');if(size){form.size=size.dataset.size;form.advanced=true;refreshUI();return;}
 const run=e.target.closest('[data-open-run]');if(run){tab='conversation';go(`runs/${run.dataset.openRun}`);return;}
 const tabs=e.target.closest('[data-tab]');if(tabs){tab=tabs.dataset.tab;refreshUI();return;}
 const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;refreshUI();return;}
 const s=e.target.closest('[data-suggestion]');if(s){const r=currentRun();r.draft=s.dataset.suggestion;persist();$('#feedback').value=r.draft;$('#feedback').focus();return;}
 const ws=e.target.closest('[data-use-workspace]');if(ws){chooseWorkspace(ws.dataset.useWorkspace);go('new');return;}
 const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;const r=currentRun();
 if(a==='new')go('new');else if(a==='runs')go('runs');else if(a==='menu'){mobileOpen=!mobileOpen;refreshUI();}
 else if(a==='open-saved'){const saved=runs.find(x=>x.state==='review')||runs.find(x=>pausedStates.includes(x.state));if(saved){tab='conversation';go(`runs/${saved.id}`);}else{toast('No suspended runs remain. Start a new task to try the review flow.');go('runs');}}
 else if(['how','repos','resume','approve','cancel','reset','connect','disconnect','pr'].includes(a)){if(a==='resume'&&r?.account==='personal'&&!connection){toast('Reconnect your ChatGPT demo account first.');return;}openModal(a);}
 else if(a==='close-modal'||a==='backdrop'&&e.target===action)closeModal();
 else if(a==='confirm-repos'){form.repos=repos.filter(repo=>document.querySelector(`[data-add-repo="${repo.id}"]`)?.checked).map(repo=>form.repos.find(r=>r.id===repo.id)?{...form.repos.find(r=>r.id===repo.id),enabled:true}:{id:repo.id,branch:'main',enabled:true});closeModal();refreshUI();}
 else if(a==='confirm-resume')resumeRun(r,$('#resume-feedback').value);
 else if(a==='compose-resume')resumeRun(r,$('#feedback').value);
 else if(a==='confirm-approve'){if(r&&r.state==='review'){r.state='completed';r.snapshot=null;r.draft='';addMessage(r,'system','You approved the result and finished the run. The sandbox and checkpoint were released. The draft PR was not merged.');persist();closeModal();refreshUI();toast('Run completed. No PR was merged.');}}
 else if(a==='confirm-cancel'){if(r){r.state='cancelled';r.snapshot=null;addMessage(r,'system','Run cancelled by you. The sandbox was released.');persist();closeModal();refreshUI();toast('Demo run cancelled.');}}
 else if(a==='suspend'){if(r&&activeStates.includes(r.state)){r.state='suspended';saveCheckpoint(r);addMessage(r,'system','You requested suspension. Workspace and session saved; sandbox execution capacity released.');persist();refreshUI();toast('Run suspended. You can resume it later.');}}
 else if(a==='send'){const text=$('#feedback').value.trim();if(!text){toast('Write a message first.');return;}addMessage(r,'user',text);addMessage(r,'agent','I received your follow-up. I’ll include it in the next step and report the result.');r.draft='';persist();refreshUI();toast('Message added to the demo conversation.');}
 else if(a==='rerun'&&r){form={...structuredClone(r),advanced:false};go('new');toast('Settings copied into a new task form.');}
 else if(a==='confirm-connect'){connection=true;persist();closeModal();refreshUI();toast('Demo connection added. No real sign-in took place.');}
 else if(a==='confirm-disconnect'){connection=false;if(form.account==='personal')form.account='company';runs.filter(x=>x.account==='personal'&&[...activeStates,'queued'].includes(x.state)).forEach(x=>{x.state='suspended';saveCheckpoint(x);addMessage(x,'system','Demo account disconnected. Run suspended until you reconnect.');});persist();closeModal();refreshUI();toast('Demo account disconnected.');}
 else if(a==='confirm-reset'){seed();connection=true;automation=true;filter='all';search='';form={...form,...structuredClone({template:'fix',title:templates.fix.title,prompt:templates.fix.prompt,workspace:'orders',repos:[{id:'orders-api',enabled:true,branch:'main'},{id:'shared-contracts',enabled:true,branch:'main'}],env:'dotnet',agent:'Codex',account:'company',size:'balanced',effort:'Standard',timeout:'30',completion:'review',advanced:false})};persist();closeModal();go('new');toast('Original demo data restored.');}
 else if(a==='toggle-automation'){automation=!automation;persist();refreshUI();}
 else if(a==='trigger-event'&&automation){const config={...structuredClone(form),template:'fix',title:'Fix issue #124: duplicate order on retry',prompt:'Investigate issue #124, reproduce the duplicate-order bug, implement a focused fix and add regression tests.',workspace:'orders',repos:[{id:'orders-api',enabled:true,branch:'main'},{id:'shared-contracts',enabled:true,branch:'main'}],env:'dotnet',agent:'Codex',account:'company',size:'balanced',completion:'review'};createRun(config,'GitHub event');}
});
document.addEventListener('keydown',e=>{if(!modalState)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusables=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal textarea,.modal select,.modal a[href]')];if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{tab='conversation';mobileOpen=false;render();window.scrollTo(0,0);});
if(!location.hash)history.replaceState(null,'','#/new');
render();setInterval(tick,800);
